function vContact(m){ if(!contactsOn()){ go('dash'); return; } const p=personById(view.contactId); if(!p){ go('contacts'); return; } const y=String(Y()), IX=contactIndex(), tags=tagsOfP(p,IX), c=companyById(p.company), ed=crmEdit(), rows=personSponsorships(p), guest=(IX.guest.get(p.id)||[]).slice().sort((a,b)=>String(b.e.date||'').localeCompare(String(a.e.date||'')));
  const given=IX.given.get(p.id)||0, givenY=r2(sum(guest.filter(({e})=>String(e.date||'').slice(0,4)===y),({e,g})=>sum(e.payments.filter(x=>+x.paddle===+g.paddle),x=>x.amount))+sum(rows.filter(r=>r.year===y&&r.roles.includes('Sponsor')),r=>r.received));
  const log=(p.log||[]).slice().sort((a,b)=>String(b.at).localeCompare(String(a.at))), when=iso=>iso?new Date(iso).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'';
  const cols='grid-template-columns:70px minmax(0,1.6fr) minmax(0,1fr) 110px 110px 100px';
  m.innerHTML=`<div class="crumb"><button id="ctBack">Contacts</button><span class="muted">/</span><span class="muted">${esc(memberName(p))}</span></div>
    <div class="phead"><div><h1 class="h1">${esc(memberName(p))}</h1><div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">${c?`<button class="chip navy" id="ctCo" style="cursor:pointer">${esc(c.name)}${p.title?' · '+esc(p.title):''}</button>`:p.title?`<span class="chip">${esc(p.title)}</span>`:''}${personTypes(p).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}${tagChips(tags)}${p.email?`<span class="chip">${esc(p.email)}</span>`:''}${p.phone?`<span class="chip">${esc(p.phone)}</span>`:''}${[p.city,p.state].filter(Boolean).length?`<span class="chip">${esc([p.city,p.state].filter(Boolean).join(', '))}</span>`:''}</div></div>
      <div class="actions">${ed?btn('Log a note','ctNote','')+btn('Edit','ctEdit','pri',I.edit):''}</div></div><div class="rule"></div>
    <div class="grid g3">${kpi('Lifetime given',fmt(given),'paid at events and on their own sponsorships')}${kpi(y,fmt(givenY),'this year')}${kpi('Events',String(guest.length),guest.length?`last ${esc(guest[0].e.name)}`:'not on a guest list yet')}</div>
    <div class="card" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Sponsorships</h2><span class="muted">Every sponsorship ${esc(p.first||'they')} has a part in — as the sponsor, the primary or billing contact, or a player</span></div></div>
      ${rows.length?`<div class="tw"><div class="t" style="min-width:760px"><div class="tr th" style="${cols}"><span>Year</span><span>Tournament / event</span><span>Level</span><span class="r">Pledged</span><span class="r">Received</span><span>Status</span></div>
      ${rows.map(r=>spRowHTML(r,cols,[r.roles.join(' · '),r.sponsorName&&!r.roles.includes('Sponsor')?'for '+r.sponsorName:'',r.kind==='event'?'Fundraising event':'Tournament',r.team?`Team ${r.team}`:''].filter(Boolean).join(' · '))).join('')}</div></div>`:`<div class="empty"><b>No sponsorships</b><span>An individual sponsor, a company’s contact or a golfer on a sponsor’s team shows here.</span></div>`}</div>
    <div class="grid g2" style="align-items:start">
      <div class="card lg pl" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Events</h2><span class="muted">Guest lists ${esc(p.first||'they')} ${guest.length?'is':'would be'} on, with the paddle and what was paid</span></div></div>
        ${guest.length?guest.map(({e,g})=>{ const T=paddleTotals(e,g.paddle), tk=e.tickets.find(t=>t.id===g.ticketId); return `<div class="lr click" data-gev="${e.id}"><div class="cell2"><span class="ln" style="font-size:15px">${esc(e.name)}</span><span class="ls">${esc([e.date?dateTxt(e.date):'',tk?`${g.qty>1?g.qty+' × ':''}${tk.name}`:'',g.table?'table '+g.table:'',g.paddle?'paddle #'+g.paddle:'',T.paid?fmt2(T.paid)+' paid':T.owed?fmt2(T.owed)+' owed':''].filter(Boolean).join(' · '))}</span></div><span class="lact"><span class="ib">${I.chev}</span></span></div>`; }).join(''):`<div class="empty"><b>No events yet</b><span>When ${esc(p.first||'they')} is on an event’s guest list it shows here.</span></div>`}</div>
      <div class="card lg pl" style="overflow:hidden"><div class="cardhead"><div><h2 class="h2">Notes</h2><span class="muted">Calls, meetings, what they said — newest first</span></div>${ed?`<div class="actions"><button class="btn sm" id="ctNote2">${I.plus}Note</button></div>`:''}</div>
        ${p.notes?`<div class="lr"><div class="cell2"><span class="ln" style="white-space:pre-wrap">${esc(p.notes)}</span><span class="ls">About ${esc(p.first||'them')}</span></div></div>`:''}
        ${log.length?log.map(n=>`<div class="lr"><div class="cell2"><span class="ln" style="white-space:pre-wrap">${esc(n.text)}</span><span class="ls">${esc(when(n.at))}${n.by?' · '+esc(n.by):''}</span></div>${ed?`<span class="lact"><button class="ib" data-ndel="${n.id}" aria-label="Remove note">${I.x}</button></span>`:''}</div>`).join(''):p.notes?'':`<div class="empty"><b>Nothing logged</b><span>Log a note after a call or a meeting so the next person knows where things stand.</span></div>`}</div>
    </div>`;
  $('ctBack').onclick=()=>go('contacts'); const E=$('ctEdit'); if(E) E.onclick=()=>editMember(memberById(p.id)); const co=$('ctCo'); if(co) co.onclick=()=>go('company',{companyId:c.id});
  ['ctNote','ctNote2'].forEach(id=>{ const b=$(id); if(b) b.onclick=()=>companyNoteDrawer(p,memberName(p)); });
  m.querySelectorAll('[data-ndel]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const n=(p.log||[]).find(x=>x.id===b.dataset.ndel); if(!n) return; p.log=p.log.filter(x=>x!==n); persist(); render(); toast('Note removed',()=>{ p.log.push(n); persist(); render(); }); });
  m.querySelectorAll('[data-gev]').forEach(r=>r.onclick=()=>go('fundev',{fid:r.dataset.gev,ftab:'guests'})); wireSpRows(m,rows); }
function companyDrawer(c,kind){ const isNew=!c; kind=isNew?(kind==='household'?'household':'company'):orgKind(c); const hh=kind==='household';
  openDrawer({kicker:backTo()[1],title:isNew?(hh?'Add household':'Add company'):c.name,body:field(hh?'Household':'Company','cdN',c?c.name:'',{ph:hh?'The Walls family':'Acme Bank'})+(contactsOn()?`<input type="hidden" id="cdK" value="${kind}">`:'')+pair(hh?field('Known as','cdI',c?c.industry||'':'',{ph:'Zach & Jen Walls'}):field('Industry','cdI',c?c.industry||'':'',{ph:'Bank, builder, dealership…'}),field(hh?'E-mail':'Website','cdW',c?(hh?c.email||'':c.website||''):''))+pair(field('Phone','cdP',c?c.phone||'':''),hh?field('Website','cdE',c?c.website||'':''):field('E-mail','cdE',c?c.email||'':'',{type:'email'}))+
      field('Address','cdA',c?c.address1||'':'')+`<div style="display:grid;grid-template-columns:minmax(0,2fr) 70px minmax(0,1fr);gap:12px">${field('City','cdC',c?c.city||'':'')}${field('State','cdS',c?c.state||'':'')}${field('Zip','cdZ',c?c.zip||'':'')}</div>`+(contactsOn()?tagsHTML('cdTg',c?manualTags(c):[]):'')+field('About','cdNo',c?c.notes||'':'',{type:'textarea',ph:hh?'How they came to the cause, what they care about':'What they do, who introduced them, what they care about'}),
    wire:r=>{ wireContactTypes(r,'cdTg'); },
    save:()=>{ const name=fv('cdN'); if(!name){ toast(hh?'Name the household':'Name the company'); return false; } const dup=companyByName(name); if(dup&&dup!==c){ toast('There is already a record called '+dup.name); return false; }
      const data={name,industry:fv('cdI'),website:hh?fv('cdE'):fv('cdW'),phone:fv('cdP'),email:hh?fv('cdW'):fv('cdE'),address1:fv('cdA'),city:fv('cdC'),state:fv('cdS'),zip:fv('cdZ'),notes:fv('cdNo')}; if($('cdTg')) data.tags=readContactTypes('cdTg');
      if(isNew){ c=Object.assign(newCompany(name,kind),data); companiesW().push(c); view.page='company'; view.companyId=c.id; }
      else { Object.assign(c,data); (db.tournaments||[]).forEach(t=>(t.sponsors||[]).forEach(s=>{ if(s.companyId===c.id) s.company=name; })); if(isClub()&&typeof fundOn==='function'&&fundOn()) fundData().events.forEach(e=>(e.sponsors||[]).forEach(s=>{ if(s.companyId===c.id) s.name=name; })); } },
    del:isNew?null:()=>{ const n=companyContacts(c.id).length, sp=sponsorshipsOf(c).filter(r=>r.linked&&r.own).length; if(!confirm(`Remove ${c.name}?${n?` Its ${n} ${n===1?'person stays':'people stay'} on the list without a ${hh?'household':'company'}.`:''}${sp?` ${sp} sponsorship${sp===1?'':'s'} keep the name but lose the link.`:''}`)) return false;
      CLUB.companies=companies().filter(x=>x!==c); persons().forEach(p=>{ if(p.company===c.id) p.company=''; }); sponsorshipsOf(c).forEach(r=>{ if(r.own&&r.s.companyId===c.id){ r.s.companyId=''; } }); view.page=backTo()[0]; },delLabel:hh?'Remove household':'Remove company'}); }
/* a contact: a directory person with a company or household, a title and a role there. The club hub writes the person; an association
   writes the same person in the club document (persist saves the club row, as a member edit does) — a new one is a directory person, not a member. */
function contactDrawer(p,c){ const isNew=!p, hh=orgKind(c)==='household';
  openDrawer({kicker:c?c.name:'Contact',title:isNew?(hh?'Add a family member':'Add contact'):memberName(p),body:pair(field('First name','ctF',p?p.first||'':''),field('Last name','ctL',p?p.last||'':(hh&&c?c.name.replace(/^the\s+/i,'').replace(/\s+(family|household)$/i,''):''))) +(hh?'':field('Title','ctT',p?p.title||'':'',{ph:'Owner, Director of Marketing…'}))+companyPickHTML('ctCo',{companyId:p?p.company:(c?c.id:''),name:''},'Company or household')+`<div id="ctCTBox">${contactTypesHTML('ctCT',p?personTypes(p):[],c)}</div>`+pair(field('E-mail','ctE',p?p.email||'':'',{type:'email'}),field('Phone','ctP',p?p.phone||'':''))+field('Notes','ctN',p?p.notes||'':'',{type:'textarea'})+(p?`<p class="hint">Everything else about ${esc(memberName(p))} — address, handicap, status — is on the <a href="#" id="ctFull">full record</a>.</p>`:''),
    wire:r=>{ wireCompanyPick(r,'ctCo',cc=>{ const box=r.querySelector('#ctCTBox'); const sel=readContactTypes('ctCT'); box.innerHTML=contactTypesHTML('ctCT',sel,cc); wireContactTypes(r,'ctCT'); }); wireContactTypes(r,'ctCT'); const f=r.querySelector('#ctFull'); if(f) f.onclick=e=>{ e.preventDefault(); closeDrawer(); editMember(memberById(p.id)); }; },
    save:()=>{ const first=fv('ctF'), last=fv('ctL'); if(!first&&!last){ toast('Enter a name'); return false; } const pk=readCompanyPick('ctCo');
      const data={first,last,title:$('ctT')?fv('ctT'):(p?p.title||'':''),company:pk.companyId,ctypes:readContactTypes('ctCT'),email:fv('ctE'),phone:fv('ctP'),notes:fv('ctN')};
      if(p) Object.assign(p,data); else CLUB.members.push(Object.assign({id:uid(),status:'Active',memberType:'Contact',source:'contact'},data)); },
    del:p?()=>{ p.company=''; toast(`${memberName(p)} is no longer under ${c?c.name:'the record'} — still on the list`); }:null,delLabel:hh?'Take out of the household':'Take off this company',delPlain:true}); }
/* a dated, signed note on a company, a household or a person */
function companyNoteDrawer(x,title){ openDrawer({kicker:title||x.name,title:'Log a note',saveLabel:'Log it',body:field('Note','cnT','',{type:'textarea',ph:'Called Dana about the Gold package — wants the foursome on Sunday, invoice to Accounts Payable.'})+pair(field('Date','cnD',todayISO(),{type:'date'}),field('By','cnB',(typeof ACCESS!=='undefined'&&ACCESS&&(ACCESS.name||ACCESS.email))||'',{ph:'Your name'})),
  save:()=>{ const text=fv('cnT'); if(!text){ toast('Write the note'); return false; } x.log=Array.isArray(x.log)?x.log:[]; const d=fv('cnD'); x.log.push({id:uid(),at:d?d+'T12:00:00.000Z':new Date().toISOString(),by:fv('cnB'),text}); }}); }
/* ---------- the rail ---------- */
NAV.push(['companies','Companies',I.org],['contacts','Contacts',I.users]);
ORG_NAV.club.push('companies','contacts'); ORG_NAV.association.push('companies');
NAV_OWNS.companies=['companies','company']; NAV_OWNS.contacts=['contacts','contact','company','members'];
NAV_GATE.companies=()=>crmOn()&&!contactsOn(); NAV_GATE.contacts=()=>contactsOn(); NAV_GATE.members=()=>!contactsOn();
(function(){ const put=(sec,after)=>{ const i=sec[1].indexOf(after); if(i>=0&&!sec[1].includes('companies')) sec[1].splice(i+1,0,'companies'); };
  NAV_SECTIONS.nonprofit.forEach(s=>{ if(s[0]==='Donors & guests'){ s[0]='Contacts'; s[1]=['contacts']; } }); NAV_SECTIONS.club.forEach(s=>{ if(s[0]==='Membership') put(s,'members'); }); NAV_SECTIONS.association.forEach(s=>{ if(s[0]==='Membership') put(s,'members'); }); })();
